pub fn algebra_structure_field_declaration(structure: Rc<Node>, field: std::string::String) -> Rc<AlgebraFieldDeclaration> {
    match crate::v2_std_node_query::conj_children_optional(structure) {
    std::option::Option::None => Rc::new(AlgebraFieldDeclaration::InhabitanceMalformed {
    cause: "algebra_structure_not_a_conj".to_string(),
}),
    Some(members) => members.iter().cloned().fold(Rc::new(AlgebraFieldDeclaration::FieldNotDeclared), |acc: Rc<AlgebraFieldDeclaration>, e: Rc<Edge>| algebra_field_declaration_join(acc, algebra_structure_edge_field_declaration(e.clone(), field.clone()))),
}
}

pub fn algebra_field_declaration_join(a: Rc<AlgebraFieldDeclaration>, b: Rc<AlgebraFieldDeclaration>) -> Rc<AlgebraFieldDeclaration> {
    match (*a.clone()).clone() {
    AlgebraFieldDeclaration::InhabitanceMalformed { cause: _, .. } => a.clone(),
    AlgebraFieldDeclaration::FieldDeclared { field_type: _, .. } => match (*b.clone()).clone() {
    AlgebraFieldDeclaration::InhabitanceMalformed { cause: _, .. } => b.clone(),
    AlgebraFieldDeclaration::FieldDeclared { field_type: _, .. } => a.clone(),
    AlgebraFieldDeclaration::FieldNotDeclared => a.clone(),
},
    AlgebraFieldDeclaration::FieldNotDeclared => b.clone(),
}
}

pub fn algebra_structure_edge_field_declaration(e: Rc<Edge>, field: std::string::String) -> Rc<AlgebraFieldDeclaration> {
    match (*e.label.clone()).clone() {
    EdgeLabel::Authored { name: name, .. } => match crate::v2_std_node_query::binder_node_parts(e.target.clone()) {
    std::option::Option::None => Rc::new(AlgebraFieldDeclaration::InhabitanceMalformed {
    cause: "algebra_structure_field_not_a_binder".to_string(),
}),
    Some(parts) => algebra_field_declaration_join(if (name.clone() == field.clone()) {
        Rc::new(AlgebraFieldDeclaration::FieldDeclared {
    field_type: parts.type_node.clone(),
})
    } else {
        Rc::new(AlgebraFieldDeclaration::FieldNotDeclared)
    }, if algebra_field_composes_a_structure(name.clone()) {
        match crate::v2_std_node_query::conj_children_optional(parts.type_node.clone()) {
    Some(_) => algebra_structure_field_declaration(parts.type_node.clone(), field.clone()),
    std::option::Option::None => Rc::new(AlgebraFieldDeclaration::InhabitanceMalformed {
    cause: "algebra_composing_field_not_a_structure".to_string(),
}),
}
    } else {
        Rc::new(AlgebraFieldDeclaration::FieldNotDeclared)
    }),
},
    EdgeLabel::StructuralLabel { label: _, .. } => Rc::new(AlgebraFieldDeclaration::InhabitanceMalformed {
    cause: "algebra_structure_edge_not_authored".to_string(),
}),
    EdgeLabel::Positional => Rc::new(AlgebraFieldDeclaration::InhabitanceMalformed {
    cause: "algebra_structure_edge_not_authored".to_string(),
}),
}
}

pub fn algebra_field_composes_a_structure(name: std::string::String) -> bool {
    algebra_structure_composing_fields().iter().cloned().fold(false, |acc: bool, f: Symbol| (acc || (f.clone() == name.clone())))
}

