pub fn equality_derived_free_monoid_generator_declaration(a: Rc<FreeMonoidGeneratorDeclaration>, b: Rc<FreeMonoidGeneratorDeclaration>) -> bool {
    match (*a.clone()).clone() {
    FreeMonoidGeneratorDeclaration::GeneratorDeclared { generator: eqa_generator, .. } => match (*b.clone()).clone() {
    FreeMonoidGeneratorDeclaration::GeneratorDeclared { generator: eqb_generator, .. } => crate::v2_std_node::node_equal_ignoring_provenance(eqa_generator.clone(), eqb_generator.clone()),
    _ => false,
},
    FreeMonoidGeneratorDeclaration::GeneratorNotDeclared => match (*b.clone()).clone() {
    FreeMonoidGeneratorDeclaration::GeneratorNotDeclared => true,
    _ => false,
},
    FreeMonoidGeneratorDeclaration::GeneratorMalformed { cause: eqa_cause, .. } => match (*b.clone()).clone() {
    FreeMonoidGeneratorDeclaration::GeneratorMalformed { cause: eqb_cause, .. } => (eqa_cause.clone() == eqb_cause.clone()),
    _ => false,
},
}
}

pub fn equality_derived_algebra_field_declaration(a: Rc<AlgebraFieldDeclaration>, b: Rc<AlgebraFieldDeclaration>) -> bool {
    match (*a.clone()).clone() {
    AlgebraFieldDeclaration::FieldDeclared { field_type: eqa_field_type, .. } => match (*b.clone()).clone() {
    AlgebraFieldDeclaration::FieldDeclared { field_type: eqb_field_type, .. } => crate::v2_std_node::node_equal_ignoring_provenance(eqa_field_type.clone(), eqb_field_type.clone()),
    _ => false,
},
    AlgebraFieldDeclaration::FieldNotDeclared => match (*b.clone()).clone() {
    AlgebraFieldDeclaration::FieldNotDeclared => true,
    _ => false,
},
    AlgebraFieldDeclaration::InhabitanceMalformed { cause: eqa_cause, .. } => match (*b.clone()).clone() {
    AlgebraFieldDeclaration::InhabitanceMalformed { cause: eqb_cause, .. } => (eqa_cause.clone() == eqb_cause.clone()),
    _ => false,
},
}
}

pub fn equality_derived_algebra_inhabitance_field_reading(a: Rc<AlgebraInhabitanceFieldReading>, b: Rc<AlgebraInhabitanceFieldReading>) -> bool {
    match (*a.clone()).clone() {
    AlgebraInhabitanceFieldReading::InhabitanceFieldRead { carrier: eqa_carrier, declaration: eqa_declaration, .. } => match (*b.clone()).clone() {
    AlgebraInhabitanceFieldReading::InhabitanceFieldRead { carrier: eqb_carrier, declaration: eqb_declaration, .. } => (crate::v2_std_node::node_equal_ignoring_provenance(eqa_carrier.clone(), eqb_carrier.clone()) && equality_derived_algebra_field_declaration(eqa_declaration.clone(), eqb_declaration.clone())),
    _ => false,
},
    AlgebraInhabitanceFieldReading::InhabitanceFieldReadMalformed { cause: eqa_cause, .. } => match (*b.clone()).clone() {
    AlgebraInhabitanceFieldReading::InhabitanceFieldReadMalformed { cause: eqb_cause, .. } => (eqa_cause.clone() == eqb_cause.clone()),
    _ => false,
},
}
}
